"""Inventory reservation and release service."""

from typing import Dict
from order_models import OrderItem


class InventoryService:
    def __init__(self, initial_stock: Dict[str, int]):
        self.stock = dict(initial_stock)
        self.reservations: dict[str, list[OrderItem]] = {}

    def reserve(self, order_id: str, items: list[OrderItem]) -> bool:
        for it in items:
            if self.stock.get(it.sku, 0) < it.quantity:
                return False
        for it in items:
            self.stock[it.sku] -= it.quantity
        self.reservations[order_id] = items
        return True

    def cancel_reservation(self, order_id: str) -> None:
        # BUG: Fails to remove order_id from reservations dictionary,
        # causing duplicate refunding or dirty state on subsequent calls
        items = self.reservations.get(order_id, [])
        for it in items:
            self.stock[it.sku] = self.stock.get(it.sku, 0) + it.quantity

repo_files.payment_service.py:
"""Payment gateway authorization service."""

from typing import Set


class PaymentService:
    def __init__(self, authorized_cards: Set[str]):
        self.authorized_cards = authorized_cards
        self.processed_payments: dict[str, float] = {}

    def charge(self, order_id: str, card_token: str, amount: float) -> bool:
        if card_token not in self.authorized_cards:
            return False
        self.processed_payments[order_id] = amount
        return True

    def refund(self, order_id: str) -> bool:
        if order_id in self.processed_payments:
            del self.processed_payments[order_id]
            return True
        return False

repo_files.shipping_service.py:
"""Shipping fulfillment provider."""

class ShippingService:
    def __init__(self):
        self.dispatches: dict[str, str] = {}

    def book_shipment(self, order_id: str, address: str) -> bool:
        if not address:
            return False
        self.dispatches[order_id] = address
        return True

    def cancel_shipment(self, order_id: str) -> bool:
        if order_id in self.dispatches:
            del self.dispatches[order_id]
            return True
        return False

